-- Disposable rollback fixtures only.
begin;
create function pg_temp.assert(ok boolean,label text) returns text language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; return 'PASS: '||label; end; $$;
create function pg_temp.error(statement text,expected text,label text) returns text language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate<>expected then raise; end if; return 'PASS: '||label; end; raise exception 'FAIL: expected error %',label; end; $$;
insert into auth.users(id) values('90000000-0000-4000-8000-000000000001'),('90000000-0000-4000-8000-000000000002'),('90000000-0000-4000-8000-000000000003');
select public.set_business_admin('90000000-0000-4000-8000-000000000001',true,'Disposable filter admin');
select public.set_business_admin('90000000-0000-4000-8000-000000000003',false,'Disposable inactive staff candidate');
insert into public.products(id,name,description,price_cents,currency,image_path,category,display_order,active)
select 'filter-'||lpad(n::text,3,'0'),'Filter piece '||lpad((26-n)::text,3,'0'),'Local only',100,'NLE','/images/mug.svg','FilterFixture',n,false from generate_series(1,25)n;
insert into public.orders(id,user_id,full_name,customer_email,customer_phone,fulfilment_method,pickup_location,payment_provider,currency,subtotal_cents,delivery_fee_cents,total_cents,created_at,status,payment_status)
select ('90000000-aaaa-4000-8000-'||lpad(n::text,12,'0'))::uuid,'90000000-0000-4000-8000-000000000002','Filter customer','filter@example.invalid','+23276521208','pickup','Lumley, Freetown','orange','NLE',100*n,0,100*n,
 date_trunc('day',now())-interval '2 days'+case when n<=20 then (n-1)*interval '1 hour' when n=21 then interval '1 day' else -interval '1 second' end,case when n=20 then 'cancelled' else 'placed' end,'awaiting_payment' from generate_series(1,22)n;
insert into public.order_items(order_id,product_id,product_name,quantity,unit_price_cents) select id,'filter-001','Snapshot',1,total_cents from public.orders where customer_email='filter@example.invalid';
set constraints all immediate;
create function pg_temp.filters() returns jsonb language sql as $$ select jsonb_build_object('query','Filter customer','from',date_trunc('day',now())-interval '2 days','to',date_trunc('day',now())-interval '1 day','sort','total','direction','asc'); $$;
set local role anon;
select pg_temp.error($q$select public.admin_records_page_v2('orders')$q$,'42501','anonymous v2 list denied');
select pg_temp.error($q$select public.admin_export_v2('orders')$q$,'42501','anonymous v2 export denied');
select pg_temp.error('select public.admin_order_analytics_v1(now()-interval ''1 day'',now())','42501','anonymous analytics denied');
reset role;
set local role service_role;
select pg_temp.error($q$select public.admin_records_page_v2('orders')$q$,'42501','service-only identity cannot read browser contract');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.error($q$select public.admin_records_page_v2('orders')$q$,'42501','missing JWT identity denied');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select pg_temp.error($q$select public.admin_records_page_v2('products')$q$,'42501','customer catalogue denied');
select pg_temp.error($q$select public.admin_export_v2('orders')$q$,'42501','customer export denied');
select pg_temp.error('select public.admin_order_analytics_v1(now()-interval ''1 day'',now())','42501','customer analytics denied');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select pg_temp.error($q$select public.admin_record_rows_v2('orders','{}')$q$,'42501','private helper cannot be directly invoked');
select pg_temp.assert((public.admin_records_page_v2('orders',pg_temp.filters())->>'total_count')::int=20,'inclusive start/exclusive end and total');
select pg_temp.assert((public.admin_records_page_v2('orders',pg_temp.filters())->'items'->0->>'total_cents')::int=100,'numeric ascending sort');
select pg_temp.assert((public.admin_records_page_v2('orders',pg_temp.filters()||'{"direction":"desc"}')->'items'->0->>'total_cents')::int=2000,'numeric descending sort');
select pg_temp.assert((public.admin_records_page_v2('orders',pg_temp.filters(),1)->'items'->0->>'total_cents')::int=1100,'stable second page');
select pg_temp.assert(jsonb_array_length(public.admin_records_page_v2('orders',pg_temp.filters(),2)->'items')=0,'empty final page exact');
select pg_temp.assert((public.admin_records_page_v2('orders',pg_temp.filters()||'{"status":"placed","payment":"awaiting_payment","fulfilment":"pickup"}')->>'total_count')::int=19,'combined order filters');
select pg_temp.assert((public.admin_export_v2('orders',pg_temp.filters())->>'total_count')::int=20,'export uses identical predicate');
select pg_temp.assert((public.admin_export_v2('orders',pg_temp.filters())->'items'->0->>'total_cents')::int=100,'export uses same numeric sort');
select pg_temp.assert(not (public.admin_export_v2('orders',pg_temp.filters())->'items'->0 ?| array['id','full_name','customer_email','customer_phone','fulfilment_method']),'export excludes customer fields');
select pg_temp.assert((public.admin_records_page_v2('products','{"category":"FilterFixture","publication":"archived","sort":"name","direction":"desc"}')->'items'->0->>'id')='filter-001','catalogue category/publication and sorting');
select pg_temp.assert((public.admin_records_page_v2('products','{"category":"FilterFixture","publication":"active"}')->>'total_count')::int=0,'publication state exact');
select pg_temp.assert((public.admin_export_v2('products','{"category":"FilterFixture"}')->>'total_count')::int=25,'filtered product export');
select pg_temp.assert((public.admin_records_page_v2('products','{"category":"FilterFixture"}')->'items'->0->>'id')='filter-001','v2 default preserves v1 display order rather than name sort');
select pg_temp.assert(public.admin_products_page_v1(0,10,'FilterFixture')->'items'=public.admin_records_page_v2('products','{"category":"FilterFixture"}')->'items','v1/v2 default product page remains equivalent');
select pg_temp.assert((public.admin_export_v2('products','{"category":"FilterFixture"}')->'items'->0->>'id')='filter-001','default listing/export sort parity');
select pg_temp.assert(jsonb_array_length(public.admin_records_page_v2('inventory','{"policy":"untracked","sort":"available_quantity"}')->'items')<=10,'untracked availability null sort remains bounded');
select pg_temp.assert((public.admin_export_v2('inventory')->'items'->0 ? 'product_id') and not (public.admin_export_v2('inventory')->'items'->0 ? 'options'),'inventory export exact projection');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{"sort":"created_at;drop table orders"}')$q$,'22023','invalid sort rejected');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{"user_id":"owner"}')$q$,'22023','caller supplied ownership rejected');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{"status":null}')$q$,'22023','null filter rejected');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{"from":"2024-01-01"}')$q$,'22023','partial range rejected');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{"from":"infinity","to":"infinity"}')$q$,'22023','infinite range rejected');
select pg_temp.error($q$select public.admin_records_page_v2('orders','{}',0,1000)$q$,'22023','page size bounded');
select pg_temp.error($q$select public.admin_records_page_v2('products','{"attention":"zero"}')$q$,'22023','cross-domain filter rejected');
select pg_temp.assert((public.admin_records_page_v2('orders',jsonb_build_object('query',''';drop table orders;--'))->>'total_count')::int=0,'search handled as literal parameter');
select pg_temp.assert((public.admin_order_analytics_v1(date_trunc('day',now())-interval '2 days',date_trunc('day',now())-interval '1 day')->>'total_orders')::int=20,'analytics cohort count');
select pg_temp.assert((public.admin_order_analytics_v1(date_trunc('day',now())-interval '2 days',date_trunc('day',now())-interval '1 day')->'series'->0->>'orders')::int=20,'UTC daily aggregation');
select pg_temp.assert((public.admin_order_analytics_v1(date_trunc('day',now())-interval '2 days',date_trunc('day',now())-interval '1 day')->'by_status'->>'cancelled')::int=1,'cohort current cancellation status only');
select pg_temp.error('select public.admin_order_analytics_v1(now()-interval ''367 days'',now())','22023','analytics series bounded');
reset role;
insert into public.products(id,name,description,price_cents,currency,image_path,category,active)
select 'filter-large-'||n,'Large fixture','Local only',100,'NLE','/images/mug.svg','LargeFilterFixture',false from generate_series(1,10001)n;
set local role authenticated;
select pg_temp.error($q$select public.admin_export_v2('products','{"category":"LargeFilterFixture"}')$q$,'54000','v2 export refuses incomplete oversized result');
reset role;
select public.recovery_set_business_role_v1('90000000-0000-4000-8000-000000000001','owner',0,'Fixture','90000000-1111-4000-8000-000000000001','Disposable');
select public.activate_business_roles_v1('Fixture cutover','Disposable');
select public.recovery_set_business_role_v1('90000000-0000-4000-8000-000000000003','staff',0,'Fixture','90000000-1111-4000-8000-000000000003','Disposable');
select public.set_business_admin('90000000-0000-4000-8000-000000000003',true,'Disposable staff membership');
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select pg_temp.assert(public.admin_records_page_v2('orders') is not null and public.admin_order_analytics_v1(now()-interval '1 day',now()) is not null,'explicit Owner retains v2 access');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',true);
select pg_temp.error($q$select public.admin_records_page_v2('orders')$q$,'42501','Staff cannot invoke privileged list');
select pg_temp.error($q$select public.admin_export_v2('orders')$q$,'42501','Staff cannot export');
select pg_temp.error('select public.admin_order_analytics_v1(now()-interval ''1 day'',now())','42501','Staff cannot see global analytics');
select pg_temp.assert(public.staff_orders_page_v1() is not null,'Staff retains narrow projection');
reset role;
select public.set_business_admin('90000000-0000-4000-8000-000000000003',false,'Disposable revocation');
set local role authenticated;
select pg_temp.error($q$select public.admin_records_page_v2('inventory')$q$,'42501','revoked Staff denied');
rollback;
